pub fn tile_dims(subdir: &str, stem: &str) -> Option<(u32, u32)> {
    ASSET_TILE_DIMS
        .iter()
        .find(|(s, n, _, _)| *s == subdir && *n == stem)
        .map(|&(_, _, tx, ty)| (tx as u32 * 8, ty as u32 * 8))
}
